export const SpeedIcon = icon(DashboardSpeed01Icon, "SpeedIcon")
export const DownloadIcon = icon(Download01Icon, "DownloadIcon")

export const AgentIcon = icon(BotIcon, "AgentIcon")
export const CallerIcon = icon(UserIcon, "CallerIcon")
export const HumanAgentIcon = icon(HeadsetIcon, "HumanAgentIcon")

export const CompletedIcon = icon(CheckmarkCircle02Icon, "CompletedIcon")
export const FailureIcon = icon(CancelCircleIcon, "FailureIcon")
export const ScheduledIcon = icon(Calendar03Icon, "ScheduledIcon")

export const CopyIcon = icon(Copy01Icon, "CopyIcon")

export const CorrectionIcon = icon(AiMagicIcon, "CorrectionIcon")
export const BackchannelIcon = icon(Message01Icon, "BackchannelIcon")
export const ToolIcon = icon(PlugSocketIcon, "ToolIcon")
export const InsightsIcon = icon(Idea01Icon, "InsightsIcon")
export const CollectedIcon = icon(Database01Icon, "CollectedIcon")
export const TechnicalIcon = icon(Wrench01Icon, "TechnicalIcon")
export const LanguageIcon = icon(GlobeIcon, "LanguageIcon")
export const OrganizationIcon = icon(Building02Icon, "OrganizationIcon")
export const OwnerIcon = icon(UserIcon, "OwnerIcon")
export const ChevronDownIcon = icon(ArrowDown01Icon, "ChevronDownIcon")

export const SearchIcon = icon(Search01Icon, "SearchIcon")
export const PrevMatchIcon = icon(ArrowUp01Icon, "PrevMatchIcon")
export const NextMatchIcon = icon(ArrowDown01Icon, "NextMatchIcon")
export const ClearSearchIcon = icon(Cancel01Icon, "ClearSearchIcon")

export const AddedIcon = icon(PlusSignCircleIcon, "AddedIcon")

export const FlagIcon = icon(Flag02Icon, "FlagIcon")

export const CustomizeIcon = icon(PreferenceVerticalIcon, "CustomizeIcon")
export const DragHandleIcon = icon(DragDropVerticalIcon, "DragHandleIcon")
export const SummaryIcon = icon(NoteIcon, "SummaryIcon")

export const CalendarIcon = icon(Calendar03Icon, "CalendarIcon")
export const QueuedIcon = icon(Clock01Icon, "QueuedIcon")
export const CancelCallIcon = icon(CancelCircleIcon, "CancelCallIcon")

export const LinkedCallIcon = icon(Link04Icon, "LinkedCallIcon")
export const OpenLinkedCallIcon = icon(ArrowRight02Icon, "OpenLinkedCallIcon")
export const RequestedIcon = icon(Comment01Icon, "RequestedIcon")

export const ShowPanelIcon = icon(SidebarRight01Icon, "ShowPanelIcon")

export const ChatChannelIcon = icon(BubbleChatIcon, "ChatChannelIcon")

"use client"

import { Button } from "@/components/ui/button"
import {
  Item,
  ItemContent,
  ItemDescription,
  ItemMedia,
  ItemTitle,
} from "@/components/ui/item"
import type { CallLink } from "@/lib/mockups/conversations-revamp-drawer-data"
import {
  LinkedCallIcon,
  OpenLinkedCallIcon,
} from "@/components/mockups/conversations-revamp/drawer/icons"

export function LinkedCall({
  label,
  link,
}: {
  /** What this call is to the one being read. */
  label: string
  link: CallLink
}) {
  return (
    <Item className="bg-card" size="sm" variant="outline">
      <ItemMedia variant="icon">
        <LinkedCallIcon />
      </ItemMedia>

      <ItemContent>
        <ItemTitle>
          {label} · {link.scenario}
        </ItemTitle>
        <ItemDescription>
          {link.status} · {link.when}
        </ItemDescription>
      </ItemContent>

      <Button size="sm" variant="outline">
        Open
        <OpenLinkedCallIcon className="rtl:rotate-180" />
      </Button>
    </Item>
  )
}

"use client"

import { Badge } from "@/components/ui/badge"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import {
  type CallLink,
  type CallSpecifics,
  type CallState,
  type ScheduleDetail,
} from "@/lib/mockups/conversations-revamp-drawer-data"
import { CancelCallDialog } from "@/components/mockups/conversations-revamp/drawer/cancel-call-dialog"
import { LinkedCall } from "@/components/mockups/conversations-revamp/drawer/linked-call"
import {
  CalendarIcon,
  QueuedIcon,
  RequestedIcon,
} from "@/components/mockups/conversations-revamp/drawer/icons"

export function PreCallPanel({
  onCancel,
  specifics,
  state,
}: {
  onCancel: () => void
  specifics: CallSpecifics
  state: Exclude<CallState, "complete">
}) {
  if (state === "queued") {
    return (
      <div className="flex h-full flex-col p-1">
        <Empty className="rounded-lg bg-muted">
          <EmptyHeader>
            <EmptyMedia variant="icon">
              <QueuedIcon />
            </EmptyMedia>
            <EmptyTitle>Waiting to dial</EmptyTitle>
            <EmptyDescription>
              This call is in the queue. There is no recording, transcript or
              outcome until it runs — they appear here once it does.
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      </div>
    )
  }

  return (
    <div className="flex h-full flex-col gap-3 p-1">
      {specifics.schedule ? (
        <ScheduledCallSection
          onCancel={onCancel}
          ranFrom={specifics.ranFrom}
          schedule={specifics.schedule}
        />
      ) : null}

      <Empty className="rounded-lg bg-muted">
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <QueuedIcon />
          </EmptyMedia>
          <EmptyTitle>Nothing recorded yet</EmptyTitle>
          <EmptyDescription>
            The recording, transcript, outcome and collected data appear here
            after the call runs.
          </EmptyDescription>
        </EmptyHeader>
      </Empty>
    </div>
  )
}

function ScheduledCallSection({
  onCancel,
  ranFrom,
  schedule,
}: {
  onCancel: () => void
  ranFrom?: CallLink
  schedule: ScheduleDetail
}) {
  const requested = schedule.origin === "requested"

  return (
    <div className="flex shrink-0 flex-col gap-4 rounded-lg bg-muted p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="flex items-center gap-2 text-sm font-medium text-primary">
          <CalendarIcon className="size-4" />
          Scheduled call
        </span>

        <div className="flex flex-wrap items-center gap-2">
          <Badge
            className={
              requested
                ? "bg-success-tint text-success-tint-foreground"
                : "bg-warning-tint text-warning-tint-foreground"
            }
            variant="secondary"
          >
            {requested ? <RequestedIcon /> : <CalendarIcon />}
            {requested ? "Customer requested" : "Inferred follow-up"}
          </Badge>
          <Badge>{schedule.trigger}</Badge>
        </div>
      </div>

      {ranFrom ? <LinkedCall label="Booked from" link={ranFrom} /> : null}

      <div className="grid gap-3 sm:grid-cols-3">
        <Field label="Dials" value={schedule.dialsAt} />
        <Field
          label="Reschedules"
          value={`${schedule.reschedules.used} of ${schedule.reschedules.limit}`}
        />
        <Field
          label="Dial attempts"
          value={`${schedule.dialAttempts.used} of ${schedule.dialAttempts.limit}`}
        />
      </div>

      <div className="flex flex-col gap-1">
        <span className="text-xs text-muted-foreground">Context brief</span>
        <p className="text-sm leading-relaxed font-medium text-foreground">
          {schedule.contextBrief}
        </p>
      </div>

      {requested ? null : (
        <p className="rounded-lg bg-card px-3 py-2 text-xs text-muted-foreground">
          Inferred by post-call analysis · {schedule.confidence}
        </p>
      )}

      <CancelCallDialog onConfirm={onCancel} />
    </div>
  )
}

function Field({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex flex-col gap-1">
      <span className="text-xs text-muted-foreground">{label}</span>
      <span className="rounded-lg bg-card px-3 py-2 text-sm text-foreground">
        {value}
      </span>
    </div>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import {
  DownloadIcon,
  PauseIcon,
  PlayCallIcon,
  SpeedIcon,
} from "@/components/mockups/conversations-revamp/drawer/icons"

const PLAYBACK_RATES = [
  { label: "0.5x speed", value: "0.5" },
  { label: "0.75x speed", value: "0.75" },
  { label: "1x speed (normal)", value: "1" },
  { label: "1.25x speed", value: "1.25" },
  { label: "1.5x speed", value: "1.5" },
  { label: "2x speed", value: "2" },
]

const BARS = 144

// Deterministic so server and client draw the same bars; Math.random would not.
function noise(index: number) {
  const value = Math.sin(index * 12.9898) * 43758.5453
  return value - Math.floor(value)
}

const WAVE = Array.from({ length: BARS }, (_, index) => {
  const position = index / BARS
  const envelope = 0.3 + 0.7 * Math.abs(Math.sin(position * Math.PI * 3.7))
  const detail = 0.35 + 0.65 * noise(index)

  return Math.min(1, Math.max(0.1, envelope * detail))
})

export function formatTimeSeconds(seconds: number) {
  return `${Math.floor(seconds / 60)}:${(seconds % 60)
    .toString()
    .padStart(2, "0")}`
}

export function RecordingPlayer({
  actions,
  at = 0,
  duration,
  flags,
  onFlagClick,
  onSeek,
}: {
  actions?: React.ReactNode
  at?: number
  duration: number
  flags?: { id: string; label: string; timestampMs: number; tone: string }[]
  onFlagClick?: (seconds: number) => void
  onSeek?: (seconds: number) => void
}) {
  const [playing, setPlaying] = React.useState(false)
  const [rate, setRate] = React.useState("1")

  const played = Math.round((at / duration) * BARS)

  return (
    <div className="flex shrink-0 flex-col overflow-hidden rounded-lg bg-muted">
      <div className="p-4">
        <div
          aria-label={onSeek ? "Seek in the recording" : undefined}
          className={cn(
            "relative flex h-10 items-center gap-px",
            onSeek &&
              "cursor-pointer focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
          )}
          onClick={
            onSeek
              ? (event) => {
                  const box = event.currentTarget.getBoundingClientRect()
                  const ratio = (event.clientX - box.left) / box.width
                  onSeek(Math.round(Math.min(Math.max(ratio, 0), 1) * duration))
                }
              : undefined
          }
          role={onSeek ? "button" : undefined}
          tabIndex={onSeek ? 0 : undefined}
        >
          {/* Bars must fill the track: seeking and the flag markers are
             measured against its full width. */}
          {Array.from({ length: BARS }, (_, index) => (
            <span
              className={cn(
                "min-w-px flex-1 rounded-sm transition-colors duration-150 ease-out-cubic motion-reduce:transition-none",
                index <= played && at > 0 ? "bg-primary-light" : "bg-border",
              )}
              key={index}
              style={{ height: `${(WAVE[index] * 100).toFixed(1)}%` }}
            />
          ))}

          {flags?.map((flag) => {
            const seconds = Math.round(flag.timestampMs / 1000)

            return (
              <Tooltip key={flag.id}>
                <TooltipTrigger
                  aria-label={`${flag.label} at ${formatTimeSeconds(seconds)}`}
                  className={cn(
                    "absolute inset-y-0 w-0.5 -translate-x-1/2 rounded-sm",
                    flag.tone,
                  )}
                  onClick={(event) => {
                    event.stopPropagation()
                    onFlagClick?.(seconds)
                  }}
                  style={{ insetInlineStart: `${(seconds / duration) * 100}%` }}
                />
                <TooltipContent>
                  {flag.label} · {formatTimeSeconds(seconds)}
                </TooltipContent>
              </Tooltip>
            )
          })}
        </div>
      </div>

      <div className="flex items-center gap-2 border-t border-border px-3 py-2">
        <Button
          aria-label={playing ? "Pause" : "Play"}
          onClick={() => {
            setPlaying(!playing)
          }}
          size="icon-sm"
        >
          {playing ? <PauseIcon /> : <PlayCallIcon />}
        </Button>

        <span className="font-mono text-sm text-muted-foreground tabular-nums">
          {formatTimeSeconds(at)} / {formatTimeSeconds(duration)}
        </span>

        <div className="ms-auto flex items-center gap-1">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button size="sm" variant="ghost">
                <SpeedIcon />
                {rate}x
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start">
              <DropdownMenuRadioGroup onValueChange={setRate} value={rate}>
                {PLAYBACK_RATES.map((option) => (
                  <DropdownMenuRadioItem
                    key={option.value}
                    value={option.value}
                  >
                    {option.label}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>

          {actions}

          <Button size="sm" variant="ghost">
            <DownloadIcon />
            Download
          </Button>
        </div>
      </div>
    </div>
  )
}

