  RECORDING_SECONDS,
  V4_TRANSCRIPT,
  type Channel,
  type TranscriptionError,
  type V4Turn,
} from "@/lib/mockups/conversations-revamp-drawer-data"
import {
  RecordingPlayer,
  formatTimeSeconds,
} from "@/components/mockups/conversations-revamp/drawer/recording-player"
import {
