function TurnLine({
  heard,
  search,
  text,
  turnIndex,
}: {
  heard: Heard[]
  search: Search
  text: string
  turnIndex: number
}) {
  const parts: React.ReactNode[] = []
  let cursor = 0

  for (const word of heard) {
    if (word.at > cursor) {
      parts.push(
        <Highlighted
          from={cursor}
          key={`line-${cursor}`}
          runKey={`${turnIndex}-line`}
          search={search}
          text={text}
          to={word.at}
        />,
      )
    }

    parts.push(
      <React.Fragment key={`heard-${word.at}`}>
        {/* Opacity, not a muted token: it must read on both bubble colours. */}
        <span className="line-through opacity-60" dir="auto">
          <Highlighted
            runKey={`${turnIndex}-heard-${word.at}`}
            search={search}
            text={word.text}
          />
        </span>{" "}
      </React.Fragment>,
    )

    cursor = word.at
  }

  parts.push(
    <Highlighted
      from={cursor}
      key="line-tail"
      runKey={`${turnIndex}-line`}
      search={search}
      text={text}
    />,
  )

  return parts
}

